// Custom Worker entry: wraps the OpenNext-generated worker to add a cron
// (scheduled) handler. `.open-next/worker.js` is generated by `npm run build`.
import handler from "./.open-next/worker.js";

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,

  // See [triggers] in wrangler.toml. Every-minute tick runs the auto-live
  // kickoff check; the daily tick runs the big-game picker. Dispatches into
  // the app without leaving the worker.
  async scheduled(event, env, ctx) {
    const origin = env.NEXT_PUBLIC_SITE_URL || "https://primepitch.daxonicstudios.workers.dev";
    const path = event.cron === "0 0 * * *" ? "/api/cron/auto-pick" : "/api/cron/auto-live";
    const request = new Request(`${origin}${path}`, {
      headers: { authorization: `Bearer ${env.CRON_SECRET || "secret"}` },
    });
    ctx.waitUntil(handler.fetch(request, env, ctx));
  },
};
